<script lang="ts">import {onMount} from 'svelte';export let id='';let session:any=null;let players='';let outcomes='';let message='';onMount(async()=>{session=await (await fetch('/api/sessions/'+id)).json();players=session.players.join(', ');outcomes=session.outcomes.join('\n')});async function save(){const r=await fetch('/api/sessions/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({players:players.split(',').map(x=>x.trim()).filter(Boolean),outcomes:outcomes.split('\n').map(x=>x.trim()).filter(Boolean)})});message=r.ok?'Saved.':(await r.json()).detail;session=await (await fetch('/api/sessions/'+id)).json()}async function end(){if(!confirm('End this session? The room will close for all guests.'))return;const r=await fetch('/api/sessions/'+id+'/end',{method:'POST'});if(r.ok)session=await r.json();else message=(await r.json()).detail}</script>
<section class="page"><a href="/sessions">← Session Log</a>{#if session}<h1>{session.game_title_snapshot}</h1><p class="muted">{new Date(session.started_at).toLocaleString()} · {session.active?'Active':'Ended'}</p>{#if session.active}<button class="danger" on:click={end}>End session</button>{/if}<label>Players<input bind:value={players} placeholder="Alex, Camille, Jordan"/></label><label>Outcomes<textarea bind:value={outcomes} placeholder="Jordan won"></textarea></label><button class="primary" on:click={save}>Save</button>{#if message}<p>{message}</p>{/if}{/if}</section>
<style>.page{padding:32px;max-width:700px;margin:auto;display:flex;flex-direction:column;gap:16px}.page h1{font-size:32px;margin-bottom:0}.muted{color:#6d6d6d}.page label{display:flex;flex-direction:column;gap:8px}.page input,.page textarea{background:#1e1c27;border:1px solid #29263c;color:#edecee;padding:10px}.page textarea{min-height:120px}.primary,.danger{padding:10px 20px;border-radius:10px;width:max-content}.primary{background:#a277ff;border:0}.danger{color:#ff6767;background:transparent;border:1px solid #ff676755}</style>
